CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL CHECK (char_length(display_name) BETWEEN 2 AND 40), age integer NOT NULL CHECK (age >= 18 AND age <= 120), bio text NOT NULL DEFAULT '' CHECK (char_length(bio) <= 500), city text NOT NULL DEFAULT '', archetype text NOT NULL DEFAULT 'Warm and caring', watching text NOT NULL DEFAULT '', avatar text NOT NULL DEFAULT 'aiko' CHECK (avatar IN ('aiko','ren','kai')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('admin','moderator')), UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,text) TO authenticated;
CREATE POLICY roles_read_own ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.account_details (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, birth_date date NOT NULL, safety_consent_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.account_details TO authenticated; GRANT ALL ON public.account_details TO service_role;
ALTER TABLE public.account_details ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.validate_adult() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.birth_date > (CURRENT_DATE - INTERVAL '18 years')::date OR NEW.birth_date < (CURRENT_DATE - INTERVAL '120 years')::date THEN RAISE EXCEPTION 'You must be at least 18 years old'; END IF; RETURN NEW; END $$;
CREATE TRIGGER adult_birth_date BEFORE INSERT OR UPDATE ON public.account_details FOR EACH ROW EXECUTE FUNCTION public.validate_adult();
CREATE POLICY account_read ON public.account_details FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY account_insert ON public.account_details FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE TABLE public.anime_preferences (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, anime text[] NOT NULL DEFAULT '{}', characters text[] NOT NULL DEFAULT '{}', moves text[] NOT NULL DEFAULT '{}', filler integer NOT NULL DEFAULT 3 CHECK(filler BETWEEN 1 AND 5), dub text NOT NULL DEFAULT 'sub' CHECK(dub IN ('sub','dub','both')), rewatch integer NOT NULL DEFAULT 2 CHECK(rewatch BETWEEN 1 AND 5), mood text NOT NULL DEFAULT 'Cozy', updated_at timestamptz NOT NULL DEFAULT now(), CHECK(cardinality(anime) <= 10), CHECK(cardinality(characters) <= 10), CHECK(cardinality(moves) <= 10));
GRANT SELECT, INSERT, UPDATE ON public.anime_preferences TO authenticated; GRANT ALL ON public.anime_preferences TO service_role;
ALTER TABLE public.anime_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY preferences_read ON public.anime_preferences FOR SELECT TO authenticated USING(user_id = auth.uid());
CREATE POLICY preferences_insert ON public.anime_preferences FOR INSERT TO authenticated WITH CHECK(user_id = auth.uid());
CREATE POLICY preferences_update ON public.anime_preferences FOR UPDATE TO authenticated USING(user_id = auth.uid()) WITH CHECK(user_id = auth.uid());
CREATE TABLE public.identity_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, id_path text NOT NULL, selfie_path text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), reviewer_note text NOT NULL DEFAULT '', submitted_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, reviewed_by uuid, CHECK(id_path <> selfie_path));
CREATE UNIQUE INDEX one_pending_identity ON public.identity_submissions(user_id) WHERE status = 'pending';
GRANT SELECT, INSERT ON public.identity_submissions TO authenticated; GRANT UPDATE(status,reviewer_note,reviewed_at,reviewed_by) ON public.identity_submissions TO authenticated; GRANT ALL ON public.identity_submissions TO service_role;
ALTER TABLE public.identity_submissions ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_verified(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT COALESCE((SELECT status = 'approved' FROM public.identity_submissions WHERE user_id = _user_id ORDER BY submitted_at DESC LIMIT 1),false) $$;
REVOKE ALL ON FUNCTION public.is_verified(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_verified(uuid) TO authenticated;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id = auth.uid() OR public.is_verified(id) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profile_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK(id = auth.uid());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id = auth.uid()) WITH CHECK(id = auth.uid());
CREATE POLICY identity_read ON public.identity_submissions FOR SELECT TO authenticated USING(user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY identity_insert ON public.identity_submissions FOR INSERT TO authenticated WITH CHECK(user_id = auth.uid() AND status = 'pending' AND reviewed_at IS NULL AND reviewed_by IS NULL AND reviewer_note = '' AND id_path LIKE auth.uid()::text || '/%' AND selfie_path LIKE auth.uid()::text || '/%' AND EXISTS(SELECT 1 FROM public.account_details WHERE user_id = auth.uid()) AND EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id = 'identity-checks' AND name = id_path AND owner_id = auth.uid()::text) AND EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id = 'identity-checks' AND name = selfie_path AND owner_id = auth.uid()::text));
CREATE POLICY identity_review ON public.identity_submissions FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') AND user_id <> auth.uid()) WITH CHECK(public.has_role(auth.uid(),'admin') AND user_id <> auth.uid() AND reviewed_by = auth.uid() AND reviewed_at IS NOT NULL AND status IN ('approved','rejected'));
CREATE POLICY identity_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id = 'identity-checks' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY identity_file_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id = 'identity-checks' AND ((storage.foldername(name))[1] = auth.uid()::text OR public.has_role(auth.uid(),'admin')));